export const gatewayRules = [
  {
    "id": "authentication",
    "title": "Authentication and credential rules",
    "summary": "Gateway v1 Beta integrations authenticate by calling register or login with an account and password. A successful response sets `accessToken` and `refreshToken` as HttpOnly cookies. Clients must use a cookie jar and return both cookies on subsequent requests.",
    "bullets": [
      "Access cookie lifetime: 30 minutes.",
      "Refresh cookie lifetime: 14 days.",
      "Production cookies are Secure.",
      "Access cookie uses SameSite Lax; refresh cookie uses SameSite Strict.",
      "Access and refresh tokens are never returned in the public JSON body.",
      "The login/register response exposes a CSRF token. Required operations send it as `X-CSRF-Token`.",
      "When refresh occurs, read the replacement from the `X-CSRF-Token` response header or `refreshableTokens.newCSRFToken`.",
      "Do not collect Notezy passwords in an untrusted third-party browser application. The Beta flow is intended for a user's own client or trusted server-side integration.",
      "Do not log request bodies for login/register, Cookie headers, Set-Cookie headers, or CSRF values."
    ]
  },
  {
    "id": "http-contract",
    "title": "HTTP contract rules",
    "summary": "The OpenAPI operation extensions schema metadata and schema metadata identify the source contracts used to generate each schema.",
    "bullets": [
      "Base path: `/api/development/v1` for the current Beta namespace.",
      "Request and response media type: `application/json`, except GraphQL Playground GET.",
      "Path resource identifiers are UUID strings unless the operation schema says otherwise.",
      "Times use RFC 3339 date-time strings.",
      "Public success envelope: `{ \"success\": true, \"data\": ..., \"exception\": null }`.",
      "Public failure envelope: `{ \"success\": false, \"data\": null, \"exception\": ... }`.",
      "`exception.retryable` is the server's explicit retry signal. A client must not infer retryability only from the message.",
      "Optional `embedded.publicId` identifies the authenticated actor.",
      "Optional `refreshableTokens.newCSRFToken` replaces the previously stored CSRF value.",
      "Unknown request fields should not be used for forward compatibility. Only documented properties form the contract.",
      "Batch requests are not atomic unless the operation description or future version explicitly promises atomicity.",
      "DELETE may be soft delete or permanent delete; permanent endpoints include `permanently` in their path."
    ]
  },
  {
    "id": "origins-and-security",
    "title": "Origin and security rules",
    "summary": "Public documentation does not itself grant a third-party origin permission to call the service.",
    "bullets": [
      "Browser requests must use `credentials: include` so cookies are accepted and returned.",
      "Cross-origin browser access works only for origins configured in the Gateway allowlist.",
      "CLI and server clients should omit Origin and Referer rather than forge an allowed browser origin.",
      "HTTPS is mandatory outside local development.",
      "Never commit Postman environments after adding credentials.",
      "Never place account passwords, cookies, CSRF tokens, realtime tickets, or authorization codes in URLs.",
      "Realtime connection and channel tickets expire after five minutes and are single-use.",
      "Treat all IDs and permissions returned by the client as untrusted; server authorization remains authoritative."
    ]
  },
  {
    "id": "rate-limits-and-retries",
    "title": "Rate limits and retry rules",
    "summary": "Gateway emits these headers on rate-limited routes:",
    "bullets": [
      "`X-RateLimit-Limit`: request allowance for the active window.",
      "`X-RateLimit-Remaining`: remaining allowance.",
      "`X-RateLimit-Reset`: Unix timestamp for the next reset estimate.",
      "`X-RateLimit-Window`: configured window duration.",
      "`X-RateLimit-Policy`: currently `hybrid-token-bucket`."
    ]
  },
  {
    "id": "versioning",
    "title": "Version and change rules",
    "summary": "The URL version (`v1`) is the compatibility boundary for request and response contracts. Repository release tags use Semantic Versioning independently.",
    "bullets": [
      "Backward-compatible fields and endpoints may be added within v1.",
      "Clients must ignore unknown response fields.",
      "Removing or changing the meaning/type of a field requires a new API version or a documented migration window.",
      "Deprecated operations remain in the OpenAPI document with a removal date before deletion.",
      "The development namespace indicates Beta stability; it does not remove the v1 compatibility obligation for documented behavior.",
      "OpenAPI, Postman, examples, rules, routes, and server schemas changes must ship together."
    ]
  }
] as const;

export const realtimeRules = [
  {
    "id": "connection-and-admission",
    "title": "Connection and admission rules",
    "summary": "Room admission uses policy version 1 and `reject-new-subscriber`. Subscriber capacity is distributed and includes both read and write subscriptions.",
    "bullets": [
      "WebSocket path: `/realtime/development/v1`.",
      "Request a connection ticket from `POST /api/development/v1/realtime/connection/ticket`.",
      "Pass the connection ticket as the sole `Sec-WebSocket-Protocol` value.",
      "Request a separate BlockPack ticket from `POST /api/development/v1/realtime/channel/block-pack/ticket` for every logical channel.",
      "Tickets are EdDSA-signed JWTs, expire after five minutes, bind to the User-Agent hash, and are single-use.",
      "A failed connection or subscription needs a newly issued ticket.",
      "One physical socket may hold at most 64 active channels. Released connector channel IDs are not reused on that socket.",
      "A new `ready` frame is a reconnect boundary. Subscribe every required channel again.",
      "Only BlockPack channels exist in protocol v1.",
      "Read tickets allow awareness traffic; only write tickets allow Yjs document mutations."
    ]
  },
  {
    "id": "frames",
    "title": "Frame rules",
    "summary": "Text control frames are UTF-8 JSON and always contain integer `version: 1` and a string `type`. Client requests should carry a unique `requestId` for correlation.",
    "bullets": []
  },
  {
    "id": "limits-and-errors",
    "title": "Limits and errors",
    "summary": "Stable error codes:",
    "bullets": [
      "Maximum public message: 1 MiB.",
      "Maximum active channels per connection: 64.",
      "Maximum concurrent root connections per user: 8.",
      "WebSocket upgrades are limited to 60 per IP per minute, with a 5/second token bucket and burst 10.",
      "Participant HTTP requests pass the same IP limit and an additional 60-per-user-per-minute limit.",
      "Per-channel outbound queue: 256 binary frames and 4 MiB payload.",
      "Awareness is replaceable ephemeral state; queued Yjs updates are never silently dropped.",
      "Full Yjs queues detach only the affected channel with `channel_backpressure`.",
      "A failed read or a write blocked for 10 seconds closes the physical socket.",
      "Server ping/pong and lease heartbeats maintain liveness; reconnect with backoff."
    ]
  },
  {
    "id": "presence-and-events",
    "title": "Presence and event rules",
    "summary": "`GET /realtime/development/v1/block-pack/{blockPackId}/participants` returns an ephemeral Redis lease snapshot. It is not an authorization source.",
    "bullets": []
  }
] as const;

